CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "274893c2-7895-4fb2-8644-16e05d91c71c",
  "snapshot_timestamp": "2026-05-21T18:19:41Z",
  "ticket_id": "1cec-29dc-4358-4e0f",
  "items": [
    {
      "original_text": "The outbound bridge processes every event added to the tracker branch between cron ticks, including events older than HEAD~1, without replaying full history on cold-start \u2014 verified by replaying three back-to-back local STATUS commits across one cron interval and observing all three reach Jira within the next outbound run, AND verified by a cold-start simulation (no checkpoint file present) that seeds at HEAD without dumping prior history into Jira",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a completed verification task with specific test scenarios executed, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "Jira-originated tickets imported via the inbound bridge preserve their description text through the plain isinstance fix \u2014 verified by creating a Jira issue with a multi-paragraph text description and confirming the local desc field contains the text content",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time verification task completed to confirm a bug fix rather than an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "Locally-authored tickets created by a contributor whose git author email is mapped in BRIDGE_USER_MAP (case-insensitive) land in Jira with the configured Jira accountId as assignee \u2014 verified by adding a mapping to the BRIDGE_USER_MAP repo variable JSON, creating a local ticket, and inspecting the resulting Jira issue",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (tickets with mapped authors are assigned correctly) that persists after implementation, though the verification clause creates minor ambiguity about whether completion is the focus"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Locally-authored tickets with no user-map entry produce a BRIDGE_ALERT and arrive in Jira explicitly unassigned via a two-step pattern (POST create then PUT /rest/api/3/issue/{key}/assignee with accountId null) \u2014 verified by creating a ticket under an unmapped git author and observing the alert plus the unassigned Jira issue",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where unmapped authors trigger alerts and unassigned tickets, verifiable through ongoing operations"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "A round-trip integration test asserts local-CREATE then outbound then mocked Jira REST v3 GET then inbound then local-state preserves description text and assignee identity end-to-end, includes a failure-injection matrix that independently reverts each of the four fixes (cursor, env_id, ADF isinstance, null-assignee) and confirms each revert produces a diagnostic test failure, and includes at least one case driven through the shell/workflow entry point rather than only the Python module boundary",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system property\u2014the presence of a comprehensive integration test with specific coverage\u2014that will remain true after completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "BRIDGE_ENV_ID is set as a non-empty repository variable, both outbound-bridge.yml and inbound-bridge.yml fail fast (precondition check) when the variable is empty, and filter_bridge_events treats empty bridge_env_id as back-compat pass-through (no filter applied) \u2014 verified by inspecting workflow run logs for the precondition check and by unit-testing filter_bridge_events with bridge_env_id empty",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system properties (variable set, fail-fast behavior, backward-compat handling) that persist after implementation rather than a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
